query:
UPDATE course_lessons SET content = REPLACE(
  REPLACE(content,
    '| Controller Type | Kp                 | Ki (Integral time Ti)     | Kd (Derivative time Td)  |',
    '| Controller Type | Kp                 | Ti (Integral Time)        | Td (Derivative Time)     |'
  ),
  '- **Note:** Ki and Kd are typically implemented as time constants in seconds.',
  '- **Note:** Ziegler-Nichols uses the **time-constant form**: Ti (integral time in seconds) and Td (derivative time in seconds). To convert to gain form: Ki = Kp/Ti and Kd = Kp × Td. Most Allen-Bradley and Siemens controllers accept time-constant form directly.'
) WHERE id = 120026;

